#!/bin/bash
#---------------------------------------------------------------------------
# build.sh : B4's programs -> b4/work/<group>/<test>.elf
#
#   ./build.sh [group ...]      (default: all the groups below)
#
# riscv-arch-test (ACT4, $ARCH_TEST, default ~/RISCV/riscv-arch-test):
#   I M Zca Zba Zbb Zbc Zbs Zicond Zicsr Zifencei Zicntr  tests/rv64i/<group>
#   Zaamo Zalrsc (step 1.4 E1c, Plan/OOC.md 29.74)
#   F D Zcd (step 1.8 U2, Plan/OOC.md 29.82: TEST_FLEN by the test's -march)
#   Sm Exceptions                                          generated by testgen
#   InterruptsSm InterruptsS (step 1.8 I1, Plan/OOC.md 29.78) generated by testgen, with MMRISC_IRQ
#   Sv Svade Svbare (step 1.8 V2, Plan/OOC.md 29.88)       tests/priv/<group>: the ones for Sv39 (and Svade, Svbare,
#                                                          Zaamo, Zalrsc; not Sv32 / 48 / 57, Zicbo*, NORUN)
#   PMP (step 1.8 P1, Plan/OOC.md 29.89)                   tests/priv/PMP: the same rule (and Zcd; not Zcb, Zcf,
#                                                          Svadu, Zicbo*)
#   dir                                                    b4/dir: directed tests
#   irq                                                    b4/irq: the interrupts' directed test (step 1.8 I1)
#   dsp                                                    Plan/fpu/gen.py's DSP kernels (step 1.8 U2: 20, each
#                                                          checking itself; tb_core -v times kstart to kend)
# The privileged tests are not in the checkout: testgen writes them to
# work/gen (Python with rich and typer). Of those, the ones whose
# REQUIRED_EXTENSIONS fit the core (I, Sm, S, U, Zca, Zicntr, Zicsr; Zaamo,
# Zalrsc since E1c: the atomics' misaligned addresses; F, D since step 1.8 U2) are built. The Interrupts groups since
# step 1.8 I1: built with MMRISC_IRQ (rvmodel_macros.h: the CLINT and the PLIC of OOO_CPU, the
# bench's sources), run on OOO_CPU alone (run_core.sh, mutate_core.py), as is b4/irq.
#
# Each test is built as the framework builds its signature ELF (-DSIGNATURE,
# the test's own -march), on act/: rvtest_config.h (the core's
# configuration, by hand), rvmodel_macros.h (HTIF), riscv_arch_test.h and
# act_sig_macros.h (sail_macros.h without Sail's CLINT), link.ld (the
# bench's 64 MB RAM). The expected values come from lock-step with Spike at
# every instruction, not from a Sail signature (Plan/CORE.md 5.7).
# b4/dir/*.S: illegal.S, the exceptions found at decode (FP instructions with
# mstatus.FS off, illegal compressed encodings and their tval, either slot);
# dcrace.S, the D$'s races behind the L2 (a fill over a valid line, FENCE.I
# behind slow writes: step 1.7 H3, Plan/OOC.md 29.58); atomic.S, the atomics
# (step 1.4 E1c, Plan/OOC.md 29.74); devld.S, loads from a device at the ROB head
# alone (step 1.8 I1); fprm.S, the rounding mode's traps (U2b); vm.S and vmx.S, Sv39's data
# and fetch sides (V1, V2); pmpx.S, PMP on the fetch word by word (P1). b4/irq/irq.S: the interrupts (OOO_CPU only).
# -mno-relax: binutils 2.43 picks how to fill a code alignment by the relax
# option at the end of the file, and the tests' .option pop sets it back
# there: LA's .p2align 5 (made under norelax) came out as zeros, not nops.
# The tests turn relaxation off anyway (the framework wants binutils 2.44).
#---------------------------------------------------------------------------
cd "$(dirname "$0")"
A=${ARCH_TEST:-$HOME/RISCV/riscv-arch-test}
CC=${CC:-/opt/riscv/bin/riscv64-unknown-elf-gcc}
PY=${PYTHON:-python3}
GROUPS_U="I M Zca Zba Zbb Zbc Zbs Zicond Zicsr Zifencei Zicntr Zaamo Zalrsc F D Zcd"
GROUPS_P="Sm Exceptions InterruptsSm InterruptsS"
GROUPS_V="Sv Svade Svbare PMP"
[ $# -gt 0 ] && SEL="$*" || SEL="$GROUPS_U $GROUPS_P $GROUPS_V dir irq dsp"
FIT=" I Sm S U Zca Zicntr Zicsr Zaamo Zalrsc F D "         # the extensions a privileged test may require
FIT_V="$FIT Sv39 Svade Svbare Zcd "                           # ... and a test of tests/priv's Sv groups (step 1.8 V2)

if [[ " $SEL " =~ " Sm " || " $SEL " =~ " Exceptions " || " $SEL " =~ " Interrupts" ]]; then
    mkdir -p work/gen
    G=$PWD/work/gen
    (cd $A && PYTHONPATH=generators/testgen/src $PY -c \
        "import sys; from testgen.cli import main; sys.argv=['testgen','testplans','-o','$G','-e','Sm,Exceptions,InterruptsSm,InterruptsS','-j','0']; main()") \
        > work/gen.log 2>&1 || { cat work/gen.log; exit 1; }
fi

fits()      # the REQUIRED_EXTENSIONS line of a test: every entry (or one of a list) is in FIT (FIT_V with a 2nd argument)
{
    local req=$(grep -m1 "REQUIRED_EXTENSIONS:" $1 | sed 's/.*: //')
    local fit="$FIT"; [ -n "$2" ] && fit="$FIT_V"
    $PY -c "
import ast, sys
fit = set('$fit'.split())
ok = all((set(e) & fit) if isinstance(e, list) else (e in fit) for e in ast.literal_eval(sys.argv[1]))
sys.exit(0 if ok else 1)" "$req"
}

n=0
for g in $SEL; do
    if [ $g = dsp ]; then
        mkdir -p work/dsp/src
        python3 ../../../Plan/fpu/gen.py work/dsp/src > /dev/null || exit 1
        for s in work/dsp/src/*.S; do
            $CC -nostdlib -nostartfiles -march=rv64gc -mabi=lp64d -T ../b2/link.ld $s -o work/dsp/$(basename $s .S).elf || exit 1
            n=$((n + 1))
        done
        continue
    fi
    if [ $g = dir ] || [ $g = irq ]; then
        mkdir -p work/$g
        for s in $g/*.S; do
            $CC -nostdlib -nostartfiles -march=rv64gc -mabi=lp64 -T ../b2/link.ld $s -o work/$g/$(basename $s .S).elf || exit 1
            n=$((n + 1))
        done
        continue
    fi
    case " $GROUPS_P " in *" $g "*) D=work/gen/priv/$g ;; *) D=$A/tests/rv64i/$g ;; esac
    case " $GROUPS_V " in *" $g "*) D=$A/tests/priv/$g ;; esac
    [ -d $D ] || { echo "build.sh: no $D"; exit 1; }
    mkdir -p work/$g
    for s in $D/*.S; do
        t=$(basename $s .S)
        case " $GROUPS_P " in *" $g "*) fits $s || continue ;; esac
        case " $GROUPS_V " in *" $g "*) fits $s v || continue ;; esac
        # (a jump to an address not canonical: the core's pc has 39 bits, so its epc and tval are not Spike's, which keeps
        #  the whole address; the specification lets them be another invalid address, which a 39-bit pc cannot give)
        case $t in Sv_sv39_canonical_*) continue ;; esac
        # (a store and a load at physical address 0 in M mode, inside the test's own PMP region: Spike faults as no memory
        #  is there; the core sends what is outside its memory to the device bus: no PMA before the SoC's map, step 2)
        case $t in PMP_Sm_cfg_A_tor_zero-*) continue ;; esac
        m=$(grep -m1 "# MARCH:" $s | sed 's/.*: //; s/\${XLEN}/64/')
        m=$(echo $m | sed 's/_sv[a-z0-9]*//g')    # (Svade, Svbare: GCC does not take them, and they name no instruction)
        case $g in Interrupts*) IRQ=-DMMRISC_IRQ ;; *) IRQ= ;; esac
        # TEST_FLEN by the test's -march (step 1.8 U2): 64 with D, 32 with F alone, else 0
        b=${m%%_*}; b=${b#rv64}
        case $b in *d*|*g*) FL=64 ;; *f*) FL=32 ;; *) FL=0 ;; esac
        $CC -I act -I $A/tests/env -T act/link.ld -O0 -g -mcmodel=medany -nostdlib -mno-relax \
            -march=$m -mabi=lp64 $IRQ -DSIGNATURE -DXLEN=64 -DTEST_FLEN=$FL "-DTEST_FILE=\"$t\"" \
            -Wl,--defsym=__stack_size=128 $s -o work/$g/$t.elf || exit 1
        n=$((n + 1))
    done
done
echo "build.sh: $n programs"
